/*
 * AJO Living 原型互動
 * 1. 保留原型互動與路由切換。
 * 2. 移除重複函式與桌面版不使用的隱藏流程。
 * 3. 維持原始 DOM id 與 onclick 呼叫，方便逐步遷移。
 */
// 1. 同步主路由外框狀態
function syncRouteShell(name){
  var isPay=name==='payment';
  document.body.classList.toggle('is-pay-route',isPay);
  var footer=document.getElementById('site-footer');
  if(footer)footer.style.display=isPay?'none':'block';
  ['compare-modal','chat-window','calc-window'].forEach(function(id){
    var el=document.getElementById(id);
    if(el)el.classList.remove('open');
  });
}

// 2. 切換主路由
function go(name){
  syncRouteShell(name);
  document.querySelectorAll('.page.on').forEach(function(el){
    el.style.opacity='0';el.style.transform='translateY(8px)';
    setTimeout(function(){el.classList.remove('on');el.style.opacity='';el.style.transform='';},200);
  });
  document.querySelectorAll('.nl,.mnl').forEach(function(el){el.classList.remove('on');});
  document.querySelectorAll('.bnav-item').forEach(function(el){el.classList.remove('on');});
  if(name==='payment'&&typeof setPaySSO==='function')setPaySSO(ajoLivingLoggedIn,'陳大文');
  setTimeout(function(){
    var p=document.getElementById('page-'+name);
    if(p){p.classList.add('on');}
    if(name==='payment'){
      if(typeof setAjoPayPage==='function')setAjoPayPage(0);
      else if(typeof dGo==='function')dGo(0,null);
    }
    var navName=({detail:'listing','market-detail':'market','service-detail':'service'})[name]||name;
    var n=document.querySelector('.nl[data-p="'+navName+'"]');if(n)n.classList.add('on');
    var mn=document.querySelector('.mnl[data-p="'+navName+'"]');if(mn)mn.classList.add('on');
    var bn=document.querySelector('.bnav-item[data-bp="'+navName+'"]');if(bn)bn.classList.add('on');
    window.scrollTo(0,0);
  },210);
}
