document.addEventListener('click',function(e){
  var btn=e.target.closest('[data-work-tab]');
  if(!btn)return;
  var tab=btn.getAttribute('data-work-tab');
  var target=btn.getAttribute('data-work-target');
  var page=document.getElementById('page-'+tab);
  if(!page)return;
  page.querySelectorAll('[data-work-tab="'+tab+'"]').forEach(function(x){x.classList.remove('on');});
  page.querySelectorAll('[data-work-panel]').forEach(function(panel){
    panel.classList.toggle('on',panel.getAttribute('data-work-panel')===target);
  });
  btn.classList.add('on');
});
function switchAccountingSubTab(btn){
  var target=btn.getAttribute('data-acct-target');
  var card=btn.closest('.work-card');
  if(!card||!target)return;
  card.querySelectorAll('.acct-tab').forEach(function(tab){tab.classList.remove('on');});
  card.querySelectorAll('.acct-subpanel').forEach(function(panel){
    panel.classList.toggle('on',panel.id===target);
  });
  btn.classList.add('on');
}
