  if(controls) controls.style.display='none';
  if(detail) detail.style.display='block';
  var set=function(id,value){var el=document.getElementById(id);if(el)el.textContent=value;};
  set('gp-detail-crumb',name);
  set('gp-detail-name',name);
  set('gp-detail-brand',brand);
  set('gp-detail-meta',brand==='地捫'?'罐頭食品 / 罐頭沙甸魚':brand+' · 超市優惠');
  set('gp-best-store',store);
  set('gp-best-offer',offer);
  set('gp-best-price',price);
  set('gp-history-store',store);
  set('gp-history-price',price);
  set('gp-history-offer',offer);
