// ── MAP VIEW TOGGLE ──
function setView(type,btn){
  document.querySelectorAll('.mtoggle').forEach(function(b){b.classList.remove('on');});
  btn.classList.add('on');
  var listEl=document.querySelector('.list-view');
  var mapEl=document.getElementById('map-view');
  if(!listEl||!mapEl)return;
  if(type==='map'){listEl.classList.add('hidden');mapEl.classList.add('on');}
  else{listEl.classList.remove('hidden');mapEl.classList.remove('on');}
}
function showMapPopup(pin,name,price,area){
  var popup=document.getElementById('map-popup');
  document.getElementById('mp-name').textContent=name;
  document.getElementById('mp-price').textContent=price;
  document.getElementById('mp-area').textContent=area;
  // position near pin
  var canvas=pin.closest('.map-canvas');
  var pr=pin.getBoundingClientRect(),cr=canvas.getBoundingClientRect();
  var left=pr.left-cr.left;var top=pr.top-cr.top;
  popup.style.left=Math.min(left-20,canvas.offsetWidth-200)+'px';
  popup.style.top=(top+10)+'px';
  popup.classList.add('open');
}
document.addEventListener('click',function(e){
  var popup=document.getElementById('map-popup');
  if(popup&&!e.target.closest('.map-pin')&&!e.target.closest('.map-popup')){popup.classList.remove('open');}
});

