// ══ THEME MODE ══
function toggleTheme(){
  var isDark=document.body.classList.toggle('dark');
  var btn=document.getElementById('theme-toggle');
  if(btn){
    var label=isDark?'切換亮色模式':'切換深色模式';
    btn.setAttribute('aria-pressed',isDark?'true':'false');
    btn.setAttribute('aria-label',label);
    btn.setAttribute('title',label);
  }
  showToast(isDark?'深色模式已開啟':'亮色模式已開啟');
}
function toggleDark(){toggleTheme();}

// ══ TOAST ══
function showToast(msg,type){
  var c=document.getElementById('toast-container');
  var t=document.createElement('div');
  t.className='toast'+(type==='success'?' success':type==='error'?' error':'');
  t.innerHTML='<span>'+msg+'</span>';
  c.appendChild(t);
  requestAnimationFrame(function(){t.classList.add('show');});
  setTimeout(function(){t.classList.remove('show');setTimeout(function(){t.remove();},300);},2500);
}

var affairsCategoryMap={
  feedback:{
    '環境與衛生':['公共空間清潔','垃圾處理','蟲害問題','環境噪音','空氣與異味'],
    '物業管理與服務':['保安服務','行政效率','住戶投訴處理'],
    '公共設施':['升降機服務','會所及康樂設施','照明與電力'],
    '系統與平台功能':['功能許願（期望平台新增的功能）'],
    '其他（Community & Others）':['養寵物問題']
  },
  repair:{
    '水務工程':['滲水/漏水','水壓不足','水龍頭/喉管損壞','排水淤塞'],
    '電力與燈光':['單位跳掣','插座故障','燈泡更換','電制開關'],
    '結構與門窗':['門鎖故障','窗戶開關','牆身裂紋','天花批盪剝落'],
    '升降機/機電':['升降機故障','電梯按鈕失靈','電動門故障'],
    '環境與清潔':['蟲鼠滋生','公共垃圾','公共地方污漬','惡臭'],
    '冷氣與通風':['冷氣不冷/漏水','通風扇損壞'],
    '會所與設施':['健身器械','燒烤爐具','兒童設施損壞'],
    '緊急類別':['火警鐘誤鳴','煤氣氣味','嚴重水浸']
  }
};
var affairsCurrentStep=1;
function getAffairsMode(){
  var modeEl=document.getElementById('affairs-request-mode');
  return modeEl&&modeEl.value==='feedback'?'feedback':'repair';
}
function getAffairsFormValues(){
  var mode=getAffairsMode();
  return {
    mode:mode,
    building:document.getElementById('affairs-building'),
    category:document.getElementById(mode==='repair'?'affairs-repair-category':'affairs-feedback-category'),
    subcategory:document.getElementById(mode==='repair'?'affairs-repair-subcategory':'affairs-feedback-subcategory'),
    content:document.getElementById(mode==='repair'?'affairs-repair-content':'affairs-feedback-content'),
    media:document.getElementById('affairs-media')
  };
}
function fillAffairsCategory(mode){
  var category=document.getElementById(mode==='repair'?'affairs-repair-category':'affairs-feedback-category');
  if(!category||category.options.length)return;
  category.innerHTML='<option value="">請選擇大類</option>'+Object.keys(affairsCategoryMap[mode]).map(function(name){return '<option>'+name+'</option>';}).join('');
}
function updateAffairsSubcategory(mode){
  var category=document.getElementById(mode==='repair'?'affairs-repair-category':'affairs-feedback-category');
  var sub=document.getElementById(mode==='repair'?'affairs-repair-subcategory':'affairs-feedback-subcategory');
  if(!category||!sub)return;
  var items=affairsCategoryMap[mode][category.value]||[];
  sub.innerHTML='<option value="">請選擇次分類</option>'+items.map(function(name){return '<option>'+name+'</option>';}).join('');
}
function setAffairsRequestMode(mode){
  var current=mode==='feedback'?'feedback':'repair';
  var hidden=document.getElementById('affairs-request-mode');
  if(hidden)hidden.value=current;
  document.querySelectorAll('[data-affairs-mode]').forEach(function(card){
    card.classList.toggle('on',card.getAttribute('data-affairs-mode')===current);
  });
  document.querySelectorAll('[data-affairs-fields]').forEach(function(field){
    field.hidden=field.getAttribute('data-affairs-fields')!==current;
  });
  document.querySelectorAll('[data-affairs-panel]').forEach(function(panel){
    panel.hidden=panel.getAttribute('data-affairs-panel')!==current;
  });
  fillAffairsCategory(current);
  updateAffairsSubcategory(current);
  setAffairsStep(1);
}
function updateAffairsReview(){
  var values=getAffairsFormValues();
  var modeText=values.mode==='repair'?'維修報修':'意見反映';
  var mediaCount=values.media&&values.media.files?values.media.files.length:0;
  var reviewMode=document.getElementById('affairs-review-mode');
  var reviewBuilding=document.getElementById('affairs-review-building');
  var reviewCategory=document.getElementById('affairs-review-category');
  var reviewSubcategory=document.getElementById('affairs-review-subcategory');
  var reviewContent=document.getElementById('affairs-review-content');
  var reviewMedia=document.getElementById('affairs-review-media');
  if(reviewMode)reviewMode.textContent=modeText;
  if(reviewBuilding)reviewBuilding.textContent=values.building&&values.building.value?values.building.value:'請選擇大廈';
  if(reviewCategory)reviewCategory.textContent=values.category&&values.category.value?values.category.value:'請選擇大類';
  if(reviewSubcategory)reviewSubcategory.textContent=values.subcategory&&values.subcategory.value?values.subcategory.value:'請選擇次分類';
  if(reviewContent)reviewContent.textContent=values.content&&values.content.value.trim()?values.content.value.trim():'請填寫內容';
  if(reviewMedia)reviewMedia.textContent=mediaCount?mediaCount+' 個檔案':'未選擇檔案';
}
function setAffairsStep(step){
  affairsCurrentStep=Math.max(1,Math.min(4,step));
  document.querySelectorAll('[data-affairs-step]').forEach(function(panel){
    panel.hidden=panel.getAttribute('data-affairs-step')!==String(affairsCurrentStep);
  });
  document.querySelectorAll('[data-affairs-step-dot]').forEach(function(dot){
    dot.classList.toggle('on',dot.getAttribute('data-affairs-step-dot')===String(affairsCurrentStep));
  });
  var prev=document.getElementById('affairs-prev-btn');
  var next=document.getElementById('affairs-next-btn');
  var submit=document.getElementById('affairs-submit-btn');
  if(prev)prev.hidden=affairsCurrentStep===1;
  if(next)next.hidden=affairsCurrentStep===4;
  if(submit)submit.hidden=affairsCurrentStep!==4;
  if(affairsCurrentStep===4)updateAffairsReview();
}
function validateAffairsStep(step){
  var values=getAffairsFormValues();
  if(step===1){
    if(!values.building||!values.building.value){showToast('請選擇大廈','error');return false;}
    if(!values.category||!values.category.value){showToast('請選擇大類','error');return false;}
    if(!values.subcategory||!values.subcategory.value){showToast('請選擇次分類','error');return false;}
  }
  if(step===2&&(!values.content||!values.content.value.trim())){showToast('請填寫內容','error');return false;}
  return true;
}
function nextAffairsStep(){
  if(!validateAffairsStep(affairsCurrentStep))return;
  setAffairsStep(affairsCurrentStep+1);
}
function toggleAffairsRecord(btn){
  var row=btn.closest('tr');
  var detail=row?row.nextElementSibling:null;
  if(!detail||!detail.classList.contains('affairs-record-detail'))return;
  var open=detail.hidden;
  detail.hidden=!open;
  btn.textContent=open?'收起內容':'查看內容';
}
function submitAffairsFeedback(){
  var values=getAffairsFormValues();
  if(!validateAffairsStep(1)||!validateAffairsStep(2))return;
  if(values.content)values.content.value='';
  if(values.media)values.media.value='';
  showToast(values.mode==='repair'?'維修報修已提交':'意見已提交','success');
  setAffairsStep(1);
}
function initAffairsRequestMode(){
  setAffairsRequestMode('repair');
}
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',initAffairsRequestMode);
}else{
  initAffairsRequestMode();
}

// ══ SCROLL PROGRESS ══
window.addEventListener('scroll',function(){
  var el=document.getElementById('scroll-progress');
  if(!el)return;
  var h=document.documentElement.scrollHeight-window.innerHeight;
  el.style.width=(h>0?(window.scrollY/h*100):0)+'%';
});

// ══ AUTOCOMPLETE ══
function showAC(input,dropId){
  var drop=document.getElementById(dropId);
  if(!drop)return;
  drop.classList.toggle('open', input.value.length>0);
}
function hideAC(dropId){
  var drop=document.getElementById(dropId);
  if(drop)drop.classList.remove('open');
}
function selectAC(val,inputId,dropId){
  var inp=document.getElementById(inputId);
  if(inp)inp.value=val;
  hideAC(dropId);
  showToast('搜尋：'+val);
}

// ══ COMPARE ══
var compareList=[];
var compareData={
  '佐敦 高級住宅':{price:'HK$36,000',area:'200呎',rooms:'1房1廁',district:'九龍',type:'住宅',floor:'高層',age:'3年'},
  '山景兩房':{price:'HK$650萬',area:'424呎',rooms:'2房',district:'新界',type:'住宅',floor:'中層',age:'12年'},
  '佐敦婚 38窗 套房':{price:'HK$6,500',area:'100呎',rooms:'6房3廁',district:'九龍',type:'住宅',floor:'中層',age:'20年'},
  '中環甲級寫字樓':{price:'HK$120,000',area:'2,400呎',rooms:'全層',district:'香港島',type:'商廈',floor:'高層',age:'5年'},
  '沙田第一城 3房':{price:'HK$18,500',area:'650呎',rooms:'3房2廁',district:'新界',type:'住宅',floor:'低層',age:'35年'}
};
function toggleCompare(cb,name,price){
  if(cb.checked){
    if(compareList.length>=3){cb.checked=false;showToast('最多比較3個物件','error');return;}
    compareList.push({name:name,price:price});
  } else {
    compareList=compareList.filter(function(x){return x.name!==name;});
  }
  updateCompareBar();
}
function addToCompare(name){
  if(compareList.find(function(x){return x.name===name;}))return;
  if(compareList.length>=3){showToast('最多比較3個物件','error');return;}
  compareList.push({name:name,price:(compareData[name]||{}).price||''});
  updateCompareBar();
}
function updateCompareBar(){
  var bar=document.getElementById('compare-bar');
  var btn=document.getElementById('compare-go-btn');
  var cnt=document.getElementById('compare-count');
  bar.classList.toggle('open',compareList.length>0);
  cnt.textContent=compareList.length+' / 3';
  if(btn)btn.disabled=compareList.length<2;
  for(var i=0;i<3;i++){
    var sl=document.getElementById('cs-'+i);
    if(!sl)continue;
    if(compareList[i]){
      sl.className='compare-slot filled';
      sl.innerHTML='<span class="compare-slot-name">'+compareList[i].name+'</span><span class="compare-slot-rm" onclick="removeCompare('+i+')">✕</span>';
    } else {
      sl.className='compare-slot';
      sl.innerHTML='+ 加入比較';
    }
  }
}
function removeCompare(i){
  compareList.splice(i,1);
  document.querySelectorAll('.compare-check').forEach(function(cb){cb.checked=false;});
  updateCompareBar();
}
function clearCompare(){
  compareList=[];
  document.querySelectorAll('.compare-check').forEach(function(cb){cb.checked=false;});
  updateCompareBar();
}
function openCompareModal(){
  var thead=document.getElementById('compare-thead');
  var tbody=document.getElementById('compare-tbody');
  if(!thead||!tbody)return;
  var fields=[
    {key:'price',label:'月租'},
    {key:'area',label:'實用面積'},
    {key:'rooms',label:'房間數目'},
    {key:'district',label:'地區'},
    {key:'type',label:'物業類型'},
    {key:'floor',label:'樓層'},
    {key:'age',label:'樓齡'}
  ];
  thead.innerHTML='<th style="width:100px;">項目</th>'+compareList.map(function(p){return '<th>'+p.name+'</th>';}).join('');
  tbody.innerHTML=fields.map(function(f){
    var vals=compareList.map(function(p){return (compareData[p.name]||{})[f.key]||'—';});
    var row='<tr><td>'+f.label+'</td>'+vals.map(function(v,i){
      var best=f.key==='price'&&vals.every(function(x,j){return j===i||parseInt(x.replace(/[^0-9]/g,''))>=parseInt(v.replace(/[^0-9]/g,''));});
      return '<td class="'+(best?'compare-best':'')+'">'+(best?'✓ ':'')+v+'</td>';
    }).join('')+'</tr>';
    return row;
  }).join('');
  document.getElementById('compare-modal').classList.add('open');
}
var compareModalEl=document.getElementById('compare-modal');
if(compareModalEl){compareModalEl.addEventListener('click',function(e){if(e.target===this)this.classList.remove('open');});}

