function renderIcctvPanel(panelId){
  var panel=document.getElementById(panelId);
  if(!panel)return;
  var select=panel.querySelector('[data-icctv-building-select]');
  var summary=panel.querySelector('[data-icctv-summary]');
  var meta=panel.querySelector('[data-icctv-building-meta]');
  var list=panel.querySelector('[data-icctv-camera-list]');
  var frame=panel.querySelector('[data-icctv-frame]');
  var empty=panel.querySelector('[data-icctv-empty]');
  var viewerMeta=panel.querySelector('[data-icctv-viewer-meta]');
  var tags=panel.querySelector('[data-icctv-tags]');
  var buildingIndex=parseInt(panel.dataset.icctvBuilding||'0',10);
  var openList=(panel.dataset.icctvOpen||'').split(',').filter(function(x){return x!=='';}).map(function(x){return parseInt(x,10);});
  var building=icctvBuildings[buildingIndex]||icctvBuildings[0];

  if(select){
    select.innerHTML=icctvBuildings.map(function(item,index){
      return '<option value="'+index+'">'+item.name+'</option>';
    }).join('');
    select.value=String(buildingIndex);
  }
  if(summary){
    summary.innerHTML=[
      '<div class="icctv-summary-card"><div class="icctv-summary-num">'+building.channels.length+'</div><div class="icctv-summary-label">可用鏡頭</div></div>',
      '<div class="icctv-summary-card"><div class="icctv-summary-num">'+(building.active?'1':'0')+'</div><div class="icctv-summary-label">在線裝置</div></div>',
      '<div class="icctv-summary-card"><div class="icctv-summary-num">'+(building.active?'正常':'待接入')+'</div><div class="icctv-summary-label">狀態</div></div>'
    ].join('');
  }
  if(meta){
    meta.innerHTML='<div class="work-row"><div><strong>'+building.name+'</strong><span>Building ID：'+building.buildingId+' · Orange Pi：'+building.device+'</span></div><span class="work-chip '+(building.active?'good':'warn')+'">'+building.status+'</span></div>';
  }
  if(tags){
    tags.innerHTML='<span class="icctv-tag '+(building.active?'on':'')+'">'+building.status+'</span><span class="icctv-tag">'+building.channels.length+' 鏡頭</span><span class="icctv-tag">Orange Pi</span>';
  }
  if(list){
    if(building.channels.length){
      list.innerHTML='<div class="icctv-camera-table"><table><thead><tr><th>鏡頭</th><th>來源</th><th>狀態</th><th>操作</th></tr></thead><tbody>'+
        building.channels.map(function(channel,index){
          var open=openList.indexOf(index)>-1;
          var row='<tr><td><div class="staff-main-text">'+channel.name+'</div><div class="staff-sub-text">'+channel.path+'</div></td><td>'+building.device+'</td><td><span class="staff-status good">可查看</span></td><td><div class="icctv-table-actions"><button class="staff-action-btn" type="button" data-icctv-panel="'+panelId+'" data-icctv-camera-index="'+index+'">'+(open?'收起':'查看')+'</button><button class="staff-action-btn" type="button" data-icctv-open-url="'+channel.url+'">新窗口</button></div></td></tr>';
          if(open){
            row+='<tr class="icctv-camera-open"><td colspan="4"><div class="icctv-inline-viewer"><iframe title="'+channel.name+'" src="'+channel.url+'" allow="autoplay; fullscreen; encrypted-media; picture-in-picture"></iframe></div></td></tr>';
          }
          return row;
        }).join('')+
      '</tbody></table></div>';
    }else{
      list.innerHTML='<div class="icctv-empty" style="position:static;min-height:160px;border-radius:8px;"><strong>暫未接入鏡頭</strong><span>此大廈尚未返回可播放的監控 URL。</span></div>';
    }
  }
  if(frame&&empty&&viewerMeta){
    var viewer=frame.closest('.icctv-viewer');
    var bar=panel.querySelector('.icctv-viewer-bar');
    if(viewer)viewer.style.display='none';
    if(bar)bar.style.display='none';
    frame.removeAttribute('src');
    delete frame.dataset.currentUrl;
  }
}

function refreshIcctvPanel(panelId){
  var panel=document.getElementById(panelId);
  if(!panel)return;
  var frames=panel.querySelectorAll('.icctv-inline-viewer iframe');
  if(frames.length){
    frames.forEach(function(frame){
      var src=frame.getAttribute('src');
      frame.setAttribute('src',src);
    });
    showToast('監控畫面已重新載入');
  }else{
    showToast('請先選擇鏡頭','error');
  }
}

function openIcctvWindow(panelId){
  var panel=document.getElementById(panelId);
  if(!panel)return;
  var frame=panel.querySelector('.icctv-inline-viewer iframe');
  if(frame&&frame.getAttribute('src')){
    window.open(frame.getAttribute('src'),'_blank','noopener');
  }else{
    showToast('請先選擇鏡頭','error');
  }
}

function initIcctvPanels(){
  ['management-icctv','affairs-icctv'].forEach(function(panelId){
    var panel=document.getElementById(panelId);
    if(!panel)return;
    panel.dataset.icctvBuilding='0';
    panel.dataset.icctvOpen='';
    renderIcctvPanel(panelId);
  });
}

document.addEventListener('change',function(e){
  var select=e.target.closest('[data-icctv-building-select]');
  if(!select)return;
  var panelId=select.getAttribute('data-icctv-building-select');
  var panel=document.getElementById(panelId);
  if(!panel)return;
  panel.dataset.icctvBuilding=select.value;
  panel.dataset.icctvOpen='';
  renderIcctvPanel(panelId);
});

document.addEventListener('click',function(e){
  var openUrl=e.target.closest('[data-icctv-open-url]');
  if(openUrl){
    window.open(openUrl.getAttribute('data-icctv-open-url'),'_blank','noopener');
    return;
  }
  var btn=e.target.closest('[data-icctv-camera-index]');
  if(!btn)return;
  var panelId=btn.getAttribute('data-icctv-panel');
  var panel=document.getElementById(panelId);
  if(!panel)return;
  var cameraIndex=parseInt(btn.getAttribute('data-icctv-camera-index'),10);
  var openList=(panel.dataset.icctvOpen||'').split(',').filter(function(x){return x!=='';}).map(function(x){return parseInt(x,10);});
  if(openList.indexOf(cameraIndex)>-1){
    openList=openList.filter(function(x){return x!==cameraIndex;});
  }else{
    openList.push(cameraIndex);
  }
  panel.dataset.icctvOpen=openList.join(',');
  renderIcctvPanel(panelId);
});

document.addEventListener('DOMContentLoaded',initIcctvPanels);

