// RIPPLE EFFECT
// ══════════════════════════════════════
document.addEventListener('click', function(e) {
  var btn = e.target.closest('.ripple-host, .nav-login, .s-btn, .lsubmit, .compare-btn, .ob-next, .npa-register, .btn-p');
  if (!btn) return;
  var circle = document.createElement('span');
  circle.className = 'ripple-circle';
  var r = Math.max(btn.offsetWidth, btn.offsetHeight);
  var rect = btn.getBoundingClientRect();
  circle.style.cssText = 'width:'+r*2+'px;height:'+r*2+'px;left:'+(e.clientX-rect.left-r)+'px;top:'+(e.clientY-rect.top-r)+'px;';
  btn.appendChild(circle);
  circle.addEventListener('animationend', function(){ circle.remove(); });
});

