function showSkeletons(containerId, count, tall) {
  var c = document.getElementById(containerId);
  if (!c) return;
  c.innerHTML = '';
  for (var i = 0; i < count; i++) {
    var h = tall ? 150 : 90;
    c.innerHTML += '<div class="gc sk-wrap"><div class="sk-img skeleton" style="height:'+h+'px;border-radius:var(--r-lg) var(--r-lg) 0 0;"></div><div style="padding:12px"><div class="sk-line skeleton w60"></div><div class="sk-line skeleton w80"></div><div class="sk-line skeleton w40"></div></div></div>';
  }
}
