// SAVED LIST
// ══════════════════════════════════════
var savedItems = [
  {name:'佐敦 高級住宅', price:'HK$36,000/月', area:'200呎', rooms:'1房1廁', district:'九龍', bg:'linear-gradient(160deg,#e8e8e8,#d0d0d0)', note:''},
  {name:'沙田第一城 3房', price:'HK$18,500/月', area:'650呎', rooms:'3房2廁', district:'新界', bg:'linear-gradient(160deg,#e4dcd8,#ccc0bc)', note:''}
];

function addToSaved(card) {
  if (!card) return;
  var name = card.dataset.name;
  var price = card.dataset.price;
  var area = card.dataset.area;
  var rooms = card.dataset.rooms;
  var district = card.dataset.district;
  if (savedItems.some(function(i){return i.name===name;})) { showToast('已在收藏清單中'); return; }
  savedItems.push({name:name,price:price,area:area,rooms:rooms,district:district,bg:'linear-gradient(160deg,#e8e8e8,#d0d0d0)',note:''});
  renderSaved();
}

function removeSaved(i) {
  savedItems.splice(i, 1);
  renderSaved();
  showToast('已移除收藏');
}

function sortSaved(by) {
  if (by === 'price-asc') savedItems.sort(function(a,b){ return parseInt(a.price.replace(/[^0-9]/g,'')) - parseInt(b.price.replace(/[^0-9]/g,'')); });
  else if (by === 'price-desc') savedItems.sort(function(a,b){ return parseInt(b.price.replace(/[^0-9]/g,'')) - parseInt(a.price.replace(/[^0-9]/g,'')); });
  renderSaved();
}

function renderSaved() {
  var grid = document.getElementById('saved-grid');
  if (!grid) return;
  if (savedItems.length === 0) {
    grid.innerHTML = "<div class=\"saved-empty\" style=\"grid-column:1/-1\"><div class=\"saved-empty-icon\"></div><div class=\"saved-empty-title\">收藏清單係空嘅</div><div class=\"saved-empty-desc\">瀏覽樓盤時點擊「 收藏」即可加入</div><button class=\"nav-login ripple-host\" onclick=\"go('listing')\">去搜尋樓盤</button></div>";
    return;
  }
  grid.innerHTML = savedItems.map(function(item, i) {
    return '<div class="saved-card reveal">' +
      '<div class="saved-card-img pat" style="background:'+item.bg+';">' +
        '<button class="saved-card-remove" onclick="removeSaved('+i+')">✕</button>' +
        '<div class="saved-card-note"><input placeholder="加備註…" value="'+item.note+'" onchange="savedItems['+i+'].note=this.value" onclick="event.stopPropagation()"></div>' +
      '</div>' +
      '<div class="saved-card-body">' +
        '<div class="saved-card-name">'+item.name+'</div>' +
        '<div class="saved-card-price">'+item.price+'</div>' +
        '<div class="saved-card-meta">'+item.district+' · '+item.area+' · '+item.rooms+'</div>' +
      '</div>' +
      '<div class="saved-card-footer">' +
        "<button class=\"saved-card-btn ripple-host\" onclick=\"openAlertModal('"+item.name+"','"+item.price+"')\"> 提醒</button>" +
        "<button class=\"saved-card-btn ripple-host primary\" onclick=\"go('detail')\">查看詳情</button>" +
      '</div>' +
    '</div>';
  }).join('');
  setTimeout(initReveal, 50);
}

// Init saved page when navigated to
document.querySelectorAll('[data-p="saved"],[data-bp="saved"]').forEach(function(btn){
  btn.addEventListener('click', function(){ setTimeout(renderSaved, 250); });
});

// ══════════════════════════════════════
// PRICE ALERT
// ══════════════════════════════════════
var priceAlerts = [];
var currentAlertProp = '';

function openAlertModal(name, currentPrice) {
  currentAlertProp = name;
  document.getElementById('alert-prop-name').textContent = name;
  document.getElementById('alert-current').textContent = '現時月租：' + currentPrice;
  document.getElementById('alert-target-input').value = '';
  renderAlertList();
  document.getElementById('alert-modal').classList.add('open');
}

function closeAlertModal() {
  document.getElementById('alert-modal').classList.remove('open');
}

function saveAlert() {
  var val = parseInt(document.getElementById('alert-target-input').value);
  if (!val || val < 1000) { showToast('請輸入有效目標價', 'error'); return; }
  // Remove existing alert for same property
  priceAlerts = priceAlerts.filter(function(a){ return a.name !== currentAlertProp; });
  priceAlerts.push({ name: currentAlertProp, target: val });
  renderAlertList();
  showToast('✓ 提醒已設定：低於 HK$' + val.toLocaleString(), 'success');
  closeAlertModal();
  // Also add to notifications
  var notifMain = document.querySelector('.notif-main');
  if(notifMain) {
    var item = document.createElement('div');
    item.className = 'notif-item unread';
    item.innerHTML = '<div class="notif-dot"></div><div class="notif-icon orange"></div><div class="notif-content"><div class="notif-title">目標價提醒已設定</div><div class="notif-desc">'+currentAlertProp+'：當月租低於 HK$'+val.toLocaleString()+' 時通知你。</div><div class="notif-time">剛剛</div></div>';
    var firstGroup = notifMain.querySelector('.notif-list');
    if(firstGroup) firstGroup.prepend(item);
  }
}

function removeAlert(i) {
  priceAlerts.splice(i, 1);
  renderAlertList();
  showToast('已移除提醒');
}

function renderAlertList() {
  var c = document.getElementById('alert-active-items');
  if (!c) return;
  if (priceAlerts.length === 0) { c.innerHTML = '<div style="font-size:11px;color:var(--ink-4);padding:8px 0;">暫無設定嘅提醒</div>'; return; }
  c.innerHTML = priceAlerts.map(function(a, i) {
    return '<div class="alert-active-item"><span class="alert-active-name">'+a.name+'</span><span class="alert-active-price">< HK$'+a.target.toLocaleString()+'</span><button class="alert-active-rm" onclick="removeAlert('+i+')">✕</button></div>';
  }).join('');
}

var alertModalEl=document.getElementById('alert-modal');
if(alertModalEl){alertModalEl.addEventListener('click', function(e){ if(e.target===this) closeAlertModal(); });}

// ══ FORM VALIDATION ══
function validatePhone(){
  var input=document.getElementById('login-phone');
  var fg=document.getElementById('fg-phone');
  if(!input||!fg)return;
  var digits=input.value.replace(/[^0-9]/g,'');
  if(input.value.length===0){fg.className='form-group';}
  else if(digits.length>=8){fg.className='form-group success';}
  else{fg.className='form-group error';}
}
function validatePwd(){
  var input=document.getElementById('login-pwd');
  var fg=document.getElementById('fg-pwd');
  if(!input||!fg)return;
  if(input.value.length===0){fg.className='form-group';}
  else if(input.value.length>=6){fg.className='form-group success';}
  else{fg.className='form-group error';}
}

